SELECT REPLACE (REPLACE(REPLACE(val,char(9),''),char(13),''),char(10),'') custid
INTO #tmpCust
FROM dbo.f_SplitString(@str, ',')
OPTION (MAXRECURSION 0)	


CREATE TABLE  #tmpCategoryHistory(custid INT, categoryID SMALLINT, CustomerClass SMALLINT, IsFinished BIT DEFAULT 0)

;WITH T AS (
SELECT (SELECT val FROM dbo.strSplit(custid,'&') where rank = 1) as custid,
		(SELECT val FROM dbo.strSplit(custid,'&') where rank = 2) as CustomerClass,
		(SELECT val FROM dbo.strSplit(custid,'&') where rank = 3) as categoryID
FROM #tmpCust
)	
INSERT INTO #tmpCategoryHistory(custid,CategoryID,CustomerClass)
SELECT custid,
	CASE CategoryID WHEN 72 THEN 52
		WHEN 73 THEN 53
		WHEN 74 THEN 54
		WHEN 75 THEN 55
		WHEN 78 THEN 58
		WHEN 79 THEN 59
		WHEN 154 THEN 54
		WHEN 157 THEN 57
		WHEN 159 THEN 59
		ELSE CategoryID END CategoryID,
	CustomerClass
FROM T

DELETE t
FROM #tmpCategoryHistory t
	INNER JOIN custinfo c WITH(NOLOCK) ON t.custid = c.custid 
WHERE t.customerClass <> c.customerClass

DECLARE @tmp TABLE (custid INT, CategoryID INT, CustomerClass SMALLINT)
	
--4k row(s) affected
WHILE(1=1)
BEGIN
	DELETE @tmp
	
	UPDATE TOP(500) t
	SET isFinished = 1
	OUTPUT DELETED.custid,DELETED.CategoryID,DELETED.CustomerClass INTO @tmp(custid,CategoryID,CustomerClass)
	FROM #tmpCategoryHistory t
	WHERE isFinished = 0
		
	IF @@ROWCOUNT = 0 
		RETURN;
		
	INSERT INTO Dep_CustCategoryHistory (custid,CategoryID,CustomerClass,CreatedDate)
	SELECT CustID, CategoryID, CustomerClass, GETDATE()
	FROM @tmp t
		
	WAITFOR DELAY '0:0:0.5'
END		


DROP TABLE #tmpCategoryHistory